// ============================================================
// SAFETY NET - Verificación de close_conversation
// ============================================================
const agentOutput = $input.first().json;
let outputText = agentOutput.output || '';
const steps = agentOutput.intermediateSteps || [];

// ============================================================
// CAPA -1: ¿Hay tag de summary (derivación a un asesor)?
//
// CAMBIO: antes, si había summary se dejaba pasar SIEMPRE, aunque
// el Agente no hubiera ejecutado close_conversation. Ahora:
//   - summary SIN close_conversation  -> force_recovery (reintenta)
//   - summary CON close_conversation  -> passthrough (inyecta `user`)
//
// Guarda anti-loop: $runIndex es el nº de corrida de ESTE nodo
// dentro de la ejecución. Se permiten hasta 2 reintentos; si el
// Agente sigue sin ejecutar la tool, se deja pasar para no
// entrar en un bucle infinito.
// ============================================================
const SUMMARY_TAG_REGEX = /【summary:/i;
if (SUMMARY_TAG_REGEX.test(outputText)) {
  const closeStep = steps.find(s =>
    s.action?.tool?.toLowerCase().startsWith('close_conversation')
  );

  // NUEVO: derivación sin la tool ejecutada
  if (!closeStep && $runIndex < 2) {
    return [{
      json: {
        action: 'force_recovery',
        reason: 'summary_sin_close_conversation',
        output: outputText,
        intermediateSteps: steps
      }
    }];
  }

  try {
    let email = '';
    if (closeStep) {
      let obs = closeStep.observation;
      if (obs && typeof obs === 'object') obs = JSON.stringify(obs);
      obs = String(obs || '');
      const m = obs.match(/"welcome_assigned_user_email"\s*:\s*"([^"]+)"/i);
      if (m && m[1]) email = m[1].trim();
    }
    if (email) {
      outputText = outputText.replace(
        /(【summary:\s*)(\{[\s\S]*?\})(\s*】)/i,
        (full, pre, jsonStr, post) => {
          try {
            const obj = JSON.parse(jsonStr);
            obj.user = email;
            return pre + JSON.stringify(obj) + post;
          } catch (e) {
            return full;
          }
        }
      );
    }
  } catch (e) {
    // no-op: si algo falla, se deja el summary tal cual
  }

  return [{
    json: {
      action: 'passthrough',
      output: outputText,
      intermediateSteps: steps
    }
  }];
}

// ============================================================
// CAPA 0: ¿Existe el campo "from" en el trigger?
// Si NO existe, está PROHIBIDO que el output contenga el
// tag de alerta de cierre de conversación.
// ============================================================
const triggerData = $('When chat message received').first().json;
const hasFromField = triggerData.hasOwnProperty('from');
if (!hasFromField) {
  const ALERT_TAG_REGEX = /【alert:\s*"?close_conversation"?】/gi;
  if (ALERT_TAG_REGEX.test(outputText)) {
    outputText = outputText.replace(ALERT_TAG_REGEX, '').trim();
  }
}

// ============================================================
// CAPA 1: Regex de palabras clave de despedida
// ============================================================
const FAREWELL_KEYWORDS = /asesor|contactar[áa]|nos comunicamos|te vamos a contactar|un representante|en breve|a la brevedad|hasta luego|hasta pronto|fue un placer|cualquier consulta|no dudes en|chau|bye|suerte|【alert:close_conversation】/i;
const hasFarewellKeyword = FAREWELL_KEYWORDS.test(outputText);

if (!hasFarewellKeyword) {
  return [{
    json: {
      action: 'passthrough',
      output: outputText,
      intermediateSteps: steps
    }
  }];
}

// ============================================================
// CAPA 2: ¿Se ejecutó close_conversation?
// ============================================================
const closeStep = steps.find(s =>
  s.action?.tool?.toLowerCase().startsWith('close_conversation')
);
const closeCalled = !!closeStep;
const hasAlertTag = outputText.includes('【alert:close_conversation】');

// Si no hay "from" y aún así quedara el alert tag (por algún borde no cubierto
// arriba), forzamos su remoción también acá antes de decidir.
if (!hasFromField && hasAlertTag) {
  outputText = outputText.replace(/【alert:\s*"?close_conversation"?】/gi, '').trim();
}

if (hasAlertTag && !closeCalled && hasFromField) {
  return [{
    json: {
      action: 'force_recovery',
      reason: 'alert_tag_sin_tool',
      output: outputText,
      intermediateSteps: steps
    }
  }];
}

if (closeCalled) {
  return [{
    json: {
      action: 'passthrough',
      output: outputText,
      intermediateSteps: steps
    }
  }];
}

return [{
  json: {
    action: 'needs_llm_verification',
    output: outputText,
    intermediateSteps: steps
  }
}];

